// src/pages/ProductDetail.jsx
import { useEffect, useState } from "react";
import { useParams, useNavigate } from "react-router-dom";
import { Helmet } from "react-helmet-async";
import axios from "axios";
import ReviewForm from "../components/ReviewForm";
import { useCartStore } from "../store/cartStore";

// Use .env backend URL
const API_URL = import.meta.env.VITE_API_BASE_URL;

// Demo products fallback
const DEMO_PRODUCTS = [
  {
    _id: "demo-1",
    name: "Laptop",
    price: 1200,
    image: "https://images.unsplash.com/photo-1496181133206-80ce9b88a853?w=400&h=400&fit=crop&crop=center",
    category: "Electronics",
    description: "High-performance laptop with latest processor, 16GB RAM, and 512GB SSD storage. Perfect for work and gaming.",
  },
  {
    _id: "demo-2",
    name: "Headphones",
    price: 150,
    image: "https://images.unsplash.com/photo-1505740420928-5e560c06d30e?w=400&h=400&fit=crop&crop=center",
    category: "Electronics",
    description: "Premium wireless headphones with active noise cancellation and superior sound quality.",
  },
  {
    _id: "demo-3",
    name: "Smartphone",
    price: 800,
    image: "https://images.unsplash.com/photo-1511707171634-5f897ff02aa9?w=400&h=400&fit=crop&crop=center",
    category: "Electronics",
    description: "Latest smartphone with advanced camera system, fast processor, and all-day battery life.",
  },
];

const DEMO_REVIEWS = [
  {
    _id: "demo-review-1",
    user: { name: "John Doe" },
    rating: 5,
    comment: "Excellent product! Highly recommended.",
    createdAt: new Date().toISOString(),
  },
  {
    _id: "demo-review-2",
    user: { name: "Jane Smith" },
    rating: 4,
    comment: "Great quality and fast delivery.",
    createdAt: new Date(Date.now() - 86400000).toISOString(),
  },
];

const ProductDetail = () => {
  const { id } = useParams(); // expects /product/:id
  const navigate = useNavigate();
  const addToCart = useCartStore((s) => s.addToCart);

  const [product, setProduct] = useState(null);
  const [reviews, setReviews] = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState("");

  useEffect(() => {
    let cancelled = false;

    const load = async () => {
      setLoading(true);
      setError("");

      // ✅ First try DEMO products
      const demoProduct = DEMO_PRODUCTS.find((p) => p._id === id);
      if (demoProduct) {
        if (!cancelled) {
          setProduct({ ...demoProduct, avgRating: 4.5 });
          setReviews(DEMO_REVIEWS);
          setLoading(false);
        }
        return;
      }

      // ✅ If not a demo product, call backend
      try {
        const productRes = await axios.get(`${API_URL}/api/products/${id}`);
        const productData =
          productRes.data?.product ?? productRes.data ?? null;

        if (!productData) {
          if (!cancelled) setError("Product not found.");
          return;
        }

        const reviewsRes = await axios.get(`${API_URL}/api/reviews/${id}`);
        const fetchedReviews = Array.isArray(reviewsRes.data)
          ? reviewsRes.data
          : reviewsRes.data?.reviews || [];

        const sum = fetchedReviews.reduce(
          (acc, r) => acc + Number(r?.rating || 0),
          0
        );
        const avg = fetchedReviews.length ? sum / fetchedReviews.length : 0;

        if (!cancelled) {
          setProduct({ ...productData, avgRating: avg });
          setReviews(fetchedReviews);
        }
      } catch (e) {
        console.error("❌ Product detail fetch failed:", e);
        if (!cancelled) {
          setError("Failed to load product details. Showing demo data.");
          // fallback demo if API fails
          const fallback = DEMO_PRODUCTS[0];
          setProduct({ ...fallback, avgRating: 4.5 });
          setReviews(DEMO_REVIEWS);
        }
      } finally {
        if (!cancelled) setLoading(false);
      }
    };

    window.scrollTo(0, 0);
    load();
    return () => {
      cancelled = true;
    };
  }, [id]);

  const handleReviewAdded = (newReview) => {
    const updated = [newReview, ...reviews];
    setReviews(updated);

    const sum = updated.reduce((acc, r) => acc + Number(r?.rating || 0), 0);
    const avg = updated.length ? sum / updated.length : 0;
    setProduct((prev) => (prev ? { ...prev, avgRating: avg } : prev));
  };

  if (loading) return <div className="p-8">Loading...</div>;
  if (!product) return <div className="p-8">Product not found</div>;

  const stars = "★".repeat(Math.round(product.avgRating || 0)) +
                "☆".repeat(5 - Math.round(product.avgRating || 0));

  return (
    <div className="max-w-4xl mx-auto p-6">
      <Helmet>
        <title>{product.name} | E-Commerce Store</title>
        <meta name="description" content={product.description || ""} />
      </Helmet>

      <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
        <img
          src={product.image}
          alt={product.name || "Product"}
          loading="lazy"
          width={400}
          height={300}
          className="w-full rounded-lg object-cover bg-gray-50"
        />

        <div>
          <h1 className="text-2xl font-bold">{product.name}</h1>
          <p className="text-gray-600 mt-2">{product.description}</p>
          <p className="text-xl font-semibold mt-4">${product.price}</p>

          <div className="flex items-center gap-2 mt-3">
            <span className="text-yellow-500">{stars}</span>
            <span className="text-sm text-gray-600">
              ({reviews.length} reviews)
            </span>
          </div>

          <button
            onClick={() => {
              addToCart?.(product);
              navigate("/cart");
            }}
            className="mt-6 bg-blue-600 text-white px-6 py-2 rounded hover:bg-blue-700"
          >
            Add to Cart
          </button>
        </div>
      </div>

      <div className="mt-10">
        <h2 className="text-xl font-semibold mb-4">Customer Reviews</h2>

        {reviews.length === 0 ? (
          <p className="text-gray-500">No reviews yet.</p>
        ) : (
          reviews.map((review) => {
            const r = review || {};
            const rating = Math.max(0, Math.min(5, Number(r.rating || 0)));
            const rStars = "★".repeat(rating) + "☆".repeat(5 - rating);

            return (
              <div key={r._id || r.id} className="border rounded-lg p-4 mb-4">
                <div className="flex items-center gap-2 mb-1">
                  <strong>{r.user?.name || "User"}</strong>
                  <span className="text-yellow-500">{rStars}</span>
                </div>
                <p className="text-gray-800">{r.comment || ""}</p>
                <p className="text-xs text-gray-400 mt-1">
                  {r.createdAt ? new Date(r.createdAt).toLocaleDateString() : ""}
                </p>
              </div>
            );
          })
        )}

        <ReviewForm
          productId={product._id || product.id}
          onReviewAdded={handleReviewAdded}
        />
      </div>
    </div>
  );
};

export default ProductDetail;
